types.text:
type FormulaNode = {
    num: number;
} | {
    ref: string;
} | {
    op: '+' | '-' | '*' | '/';
    args: [
        FormulaNode,
        FormulaNode
    ];
};

interface Score {
    id: string;
    label: string;
    formula: FormulaNode;
    unanswered: 'no-score' | 'zero';
    decimals?: number;
    showToRespondent?: boolean;
}

interface ScoreResult {
    groupId: string;
    scoreId: string;
    label: string;
    path: (string | number)[];
    value: number | null;
    reason?: 'unanswered' | 'invalid';
}
